// ---------------------------------------------------------------- persone realistiche (proporzioni adulte, snodi per sedersi e camminare)
const DONNE = new Set(['capo', 'brand', 'audit', 'copywriter', 'calendario', 'trend', 'immagini', 'ecommerce', 'booking', 'contabile', 'idee', 'stella', 'scout_tt', 'scout_ig', 'occhi', 'analista', 'copy', 'vfx', 'sottotitoli', 'revisore']);
