    const anca = new THREE.Group(); anca.position.set(0.085 * l, 0, 0); fianchi.add(anca);
    const coscia = ombra(new THREE.Mesh(geo('cos', () => new THREE.CapsuleGeometry(0.068, 0.33, 4, 12)), pant)); coscia.position.y = -0.21; anca.add(coscia);
    const ginocchio = new THREE.Group(); ginocchio.position.y = -0.43; anca.add(ginocchio);
