    const piede = ombra(new THREE.Mesh(geo('pie', () => new RoundedBoxGeometry(0.1, 0.07, 0.24, 2, 0.03)), scarpe)); piede.position.set(0, -0.44, -0.05); ginocchio.add(piede);
    gambe.push({ anca, ginocchio });
